ALTER TABLE public.advertisements DROP CONSTRAINT advertisements_placement_check;
ALTER TABLE public.advertisements ADD CONSTRAINT advertisements_placement_check CHECK (placement IN ('home','home_featured_extra','home_trending','home_trending_extra','home_middle','home_movies_extra','home_tv','home_indo','home_bottom','home_bottom_extra','details','details_bottom','catalog_top','catalog_bottom','search_top','search_bottom','watch_top','watch_bottom','watch_episodes','watch_recommendations','party_top','party_bottom','party_directory_top','party_directory_bottom','collection_top','collection_bottom','watchlist_top','watchlist_bottom','browse_top','browse_bottom','preroll','footer','details_2','details_3','details_bottom_2','details_bottom_3','catalog_top_2','catalog_top_3','catalog_bottom_2','catalog_bottom_3','search_top_2','search_top_3','search_bottom_2','search_bottom_3','watch_top_2','watch_top_3','watch_bottom_2','watch_bottom_3','watch_episodes_2','watch_episodes_3','watch_recommendations_2','watch_recommendations_3','party_top_2','party_top_3','party_bottom_2','party_bottom_3','party_directory_top_2','party_directory_top_3','party_directory_bottom_2','party_directory_bottom_3','collection_top_2','collection_top_3','collection_bottom_2','collection_bottom_3','watchlist_top_2','watchlist_top_3','watchlist_bottom_2','watchlist_bottom_3','browse_top_2','browse_top_3','browse_bottom_2','browse_bottom_3'));
ALTER TABLE public.watch_parties ADD COLUMN visibility text NOT NULL DEFAULT 'private' CHECK (visibility IN ('public','private'));
ALTER TABLE public.watch_parties ADD COLUMN is_active boolean NOT NULL DEFAULT true;
ALTER TABLE public.watch_parties ADD COLUMN last_active_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE public.watch_parties ADD COLUMN playback_time double precision NOT NULL DEFAULT 0;
ALTER TABLE public.watch_parties ADD COLUMN playback_action text NOT NULL DEFAULT 'pause' CHECK (playback_action IN ('play','pause','seek'));
ALTER TABLE public.watch_parties ADD COLUMN playback_updated_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE public.party_secrets (code text PRIMARY KEY REFERENCES public.watch_parties(code) ON DELETE CASCADE, pin_hash text NOT NULL);
GRANT ALL ON public.party_secrets TO service_role;
ALTER TABLE public.party_secrets ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.party_members (code text NOT NULL REFERENCES public.watch_parties(code) ON DELETE CASCADE, user_id uuid NOT NULL, display_name text NOT NULL CHECK (char_length(display_name) BETWEEN 1 AND 80), last_seen_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(code,user_id));
GRANT SELECT ON public.party_members TO authenticated;
GRANT ALL ON public.party_members TO service_role;
ALTER TABLE public.party_members ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.party_join_attempts (user_id uuid PRIMARY KEY, attempts integer NOT NULL DEFAULT 0, window_start timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.party_join_attempts TO service_role;
ALTER TABLE public.party_join_attempts ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.party_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL REFERENCES public.watch_parties(code) ON DELETE CASCADE, user_id uuid NOT NULL, display_name text NOT NULL, text text NOT NULL CHECK (char_length(btrim(text)) BETWEEN 1 AND 300), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.party_messages TO authenticated;
GRANT ALL ON public.party_messages TO service_role;
ALTER TABLE public.party_messages ENABLE ROW LEVEL SECURITY;
CREATE INDEX party_messages_room_time ON public.party_messages(code,created_at DESC);
CREATE FUNCTION public.is_party_member(p_code text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.watch_parties p WHERE p.code=p_code AND p.is_active AND (p.host_id=auth.uid() OR EXISTS(SELECT 1 FROM public.party_members m WHERE m.code=p.code AND m.user_id=auth.uid()))); $$;
REVOKE ALL ON FUNCTION public.is_party_member(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.is_party_member(text) TO authenticated;
CREATE POLICY "room members read presence" ON public.party_members FOR SELECT TO authenticated USING (public.is_party_member(code));
CREATE POLICY "room members read chat" ON public.party_messages FOR SELECT TO authenticated USING (public.is_party_member(code));
CREATE POLICY "room members send chat" ON public.party_messages FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND public.is_party_member(code) AND EXISTS(SELECT 1 FROM public.party_members m WHERE m.code=party_messages.code AND m.user_id=auth.uid() AND m.display_name=party_messages.display_name));
REVOKE INSERT,UPDATE ON public.watch_parties FROM authenticated;
GRANT UPDATE(season,episode,is_active,playback_time,playback_action,playback_updated_at) ON public.watch_parties TO authenticated;
CREATE POLICY "host updates party playback" ON public.watch_parties FOR UPDATE TO authenticated USING (host_id=auth.uid()) WITH CHECK(host_id=auth.uid());
CREATE FUNCTION public.create_watch_party(p_code text,p_type text,p_tmdb_id integer,p_title text,p_season integer,p_episode integer,p_visibility text,p_pin text,p_name text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
IF p_code !~ '^[A-F0-9]{32}$' OR p_type NOT IN ('movie','tv') OR p_tmdb_id<=0 OR p_visibility NOT IN ('public','private') OR char_length(p_title)>300 OR char_length(p_name) NOT BETWEEN 1 AND 80 OR (p_type='tv' AND (p_season IS NULL OR p_episode IS NULL OR p_season<1 OR p_episode<1)) THEN RAISE EXCEPTION 'Invalid room'; END IF;
IF p_visibility='private' AND (p_pin IS NULL OR p_pin !~ '^[0-9]{4,8}$') THEN RAISE EXCEPTION 'Private rooms require a 4-8 digit PIN'; END IF;
INSERT INTO public.watch_parties(code,host_id,media_type,tmdb_id,title,season,episode,visibility) VALUES(p_code,auth.uid(),p_type,p_tmdb_id,p_title,p_season,p_episode,p_visibility);
IF p_visibility='private' THEN INSERT INTO public.party_secrets VALUES(p_code,extensions.crypt(p_pin,extensions.gen_salt('bf',10))); END IF;
INSERT INTO public.party_members(code,user_id,display_name) VALUES(p_code,auth.uid(),p_name);
RETURN p_code; END; $$;
REVOKE ALL ON FUNCTION public.create_watch_party(text,text,integer,text,integer,integer,text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_watch_party(text,text,integer,text,integer,integer,text,text,text) TO authenticated;
CREATE FUNCTION public.join_watch_party(p_code text,p_pin text,p_name text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE room public.watch_parties; secret text; attempt public.party_join_attempts; BEGIN
IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
IF p_code IS NULL OR p_code !~ '^([A-Z0-9]{6}|[A-F0-9]{32})$' OR char_length(p_name) NOT BETWEEN 1 AND 80 THEN RETURN false; END IF;
INSERT INTO public.party_join_attempts(user_id) VALUES(auth.uid()) ON CONFLICT DO NOTHING;
SELECT * INTO attempt FROM public.party_join_attempts WHERE user_id=auth.uid() FOR UPDATE;
IF attempt.window_start<now()-interval '10 minutes' THEN UPDATE public.party_join_attempts SET attempts=0,window_start=now() WHERE user_id=auth.uid(); attempt.attempts:=0; END IF;
SELECT * INTO room FROM public.watch_parties WHERE code=p_code AND is_active;
IF NOT FOUND THEN RETURN false; END IF;
IF room.host_id<>auth.uid() AND NOT EXISTS(SELECT 1 FROM public.party_members WHERE code=p_code AND user_id=auth.uid()) THEN
IF attempt.attempts>=10 THEN RETURN false; END IF;
SELECT pin_hash INTO secret FROM public.party_secrets WHERE code=p_code;
IF room.visibility='private' AND secret IS NOT NULL AND (p_pin IS NULL OR p_pin !~ '^[0-9]{4,8}$' OR extensions.crypt(p_pin,secret)<>secret) THEN UPDATE public.party_join_attempts SET attempts=attempts+1 WHERE user_id=auth.uid(); RETURN false; END IF;
END IF;
INSERT INTO public.party_members(code,user_id,display_name,last_seen_at) VALUES(p_code,auth.uid(),p_name,now()) ON CONFLICT(code,user_id) DO UPDATE SET last_seen_at=now();
RETURN true; END; $$;
REVOKE ALL ON FUNCTION public.join_watch_party(text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.join_watch_party(text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.get_watch_party_by_code(p_code text) RETURNS SETOF public.watch_parties LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required' USING ERRCODE='42501'; END IF; IF public.is_party_member(p_code) THEN RETURN QUERY SELECT p.* FROM public.watch_parties p WHERE p.code=p_code LIMIT 1; END IF; END; $$;
CREATE FUNCTION public.party_heartbeat(p_code text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_party_member(p_code) THEN RETURN false; END IF; UPDATE public.party_members SET last_seen_at=now() WHERE code=p_code AND user_id=auth.uid(); UPDATE public.watch_parties SET last_active_at=now() WHERE code=p_code AND host_id=auth.uid(); RETURN true; END; $$;
REVOKE ALL ON FUNCTION public.party_heartbeat(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.party_heartbeat(text) TO authenticated;
CREATE FUNCTION public.list_public_watch_parties() RETURNS TABLE(code text,title text,media_type text,tmdb_id integer,season integer,episode integer,viewers bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.code,p.title,p.media_type,p.tmdb_id,p.season,p.episode,(SELECT count(*) FROM public.party_members m WHERE m.code=p.code AND m.last_seen_at>now()-interval '2 minutes') FROM public.watch_parties p WHERE p.visibility='public' AND p.is_active AND p.last_active_at>now()-interval '2 minutes' ORDER BY p.last_active_at DESC LIMIT 60; $$;
REVOKE ALL ON FUNCTION public.list_public_watch_parties() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.list_public_watch_parties() TO anon,authenticated;
COMMENT ON FUNCTION public.get_watch_party_by_code(text) IS 'Room metadata is available only after server-verified join; PIN hashes remain in a locked separate table. Existing invite-only rooms retain their links.';